1	package zkcircuit
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"hash"
11		"io"
12		"math"
13		"math/big"
14		"sort"
15	)
16	
17	// This file implements R1CS-style constraint definitions: their strict JSON
18	// form, validation against the declared wire layout of a circuit version, a
19	// canonical form used both for persistence and for artifact hashing, and the
20	// modular a·b = c evaluation used by input checking.
21	
22	// maxModulus bounds accepted moduli. The bound keeps every reduced field
23	// element and coefficient inside int32, which makes all constraint
24	// arithmetic exact in int64 (a product of two residues is at most
25	// (p-1)^2 < 2^62).
26	const maxModulus = 2147483647
27	
28	// Term is one wire reference with its coefficient: coeff * value(wire).
29	type Term struct {
30		Wire  int    `json:"wire"`
31		Coeff string `json:"coeff"`
32	}
33	
34	// Constraint is one a·b = c equation modulo the definition's field. Each
35	// slice is a sum of terms; an empty slice is the zero linear combination.
36	type Constraint struct {
37		A []Term `json:"a"`
38		B []Term `json:"b"`
39		C []Term `json:"c"`
40	}
41	
42	// Definition is an importable constraint set. The JSON file carries modulus
43	// as a decimal string and an ordered constraints array.
44	type Definition struct {
45		Modulus     string       `json:"modulus"`
46		Constraints []Constraint `json:"constraints"`
47	}
48	
49	// Artifact is the result of compiling one frozen circuit version. It binds
50	// the version's name, version number, modulus and constraint count to a
51	// stable SHA-256 hash; the same logical circuit always compiles to the same
52	// artifact.
53	type Artifact struct {
54		Name        string
55		Version     int
56		Modulus     int
57		Constraints int
58		Hash        string
59	}
60	
61	// CheckResult is the verdict of testing one input assignment against a
62	// compiled artifact. Satisfied reports whether every constraint holds;
63	// FirstFailure is the 1-based index of the first failing constraint, zero
64	// when the assignment satisfies the circuit.
65	type CheckResult struct {
66		Satisfied    bool
67		Hash         string
68		FirstFailure int
69	}
70	
71	// Witness is one input assignment: values for the declared public and
72	// private wires, in declaration order. Values are arbitrary-length signed
73	// decimal strings interpreted modulo the circuit's field.
74	type Witness struct {
75		Public  []string
76		Private []string
77	}
78	
79	// ---- parsed / canonical in-memory representation -------------------------
80	
81	// parsedTerm is a validated term whose coefficient has been reduced into
82	// [0, modulus).
83	type parsedTerm struct {
84		wire  int
85		value int64 // coefficient mod modulus
86	}
87	
88	// canonicalConstraint groups merged terms by wire.
89	type canonicalConstraint struct {
90		a, b, c []parsedTerm
91	}
92	
93	// canonicalDefinition is a fully validated constraint set in its canonical
94	// form: terms merged per wire, reduced modulo p, zeros removed, wires sorted
95	// ascending within each linear combination.
96	type canonicalDefinition struct {
97		modulus     int64
98		public      int
99		private     int
100		constraints []canonicalConstraint
101	}
102	
103	// maxWire returns the largest wire index referenced anywhere.
104	func (d *canonicalDefinition) maxWire() int {
105		max := 0
106		for _, con := range d.constraints {
107			for _, group := range [][]parsedTerm{con.a, con.b, con.c} {
108				for _, t := range group {
109					if t.wire > max {
110						max = t.wire
111					}
112				}
113			}
114		}
115		return max
116	}
117	
118	// compatibleWith reports whether the definition stays legal when its
119	// version declares the given counts: the constraint count must match and
120	// every referenced wire must still lie inside the declared layout.
121	func (d *canonicalDefinition) compatibleWith(constraints, public, private int) bool {
122		if len(d.constraints) != constraints {
123			return false
124		}
125		bound, ok := wireUpperBound(public, private)
126		if !ok {
127			return false
128		}
129		return d.maxWire() <= bound
130	}
131	
132	// wireUpperBound returns the highest input-wire index the declared layout
133	// names — public + private — reporting ok=false when that sum would wrap the
134	// platform's int. Every reachable caller has already passed the layout rule
135	// 1 + public + private <= M, so ok=false marks an unrepresentable layout and
136	// is never silently treated as a small (possibly negative) bound.
137	func wireUpperBound(public, private int) (bound int, ok bool) {
138		if public > math.MaxInt-private {
139			return 0, false
140		}
141		return public + private, true
142	}
143	
144	// toExport renders the canonical form as the public Definition type, with
145	// coefficients reduced to decimal strings in [0, modulus).
146	func (d *canonicalDefinition) toExport() Definition {
147		combo := func(terms []parsedTerm) []Term {
148			r := make([]Term, 0, len(terms))
149			for _, t := range terms {
150				r = append(r, Term{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
151			}
152			return r
153		}
154		cons := make([]Constraint, 0, len(d.constraints))
155		for _, con := range d.constraints {
156			cons = append(cons, Constraint{A: combo(con.a), B: combo(con.b), C: combo(con.c)})
157		}
158		return Definition{Modulus: fmt.Sprintf("%d", d.modulus), Constraints: cons}
159	}
