117	// canonicalEnvelopeField reports the standard lowercase name of one of the
118	// five envelope fields when key names it under any ASCII letter-case spelling
119	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
120	// tokenizer, so an escaped spelling of any such form lands here too. A
121	// non-canonical key (different length or a mismatching byte, including
122	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
123	func canonicalEnvelopeField(key string) string {
124		for _, field := range envelopeTopFields {
125			if len(key) != len(field) {
126				continue
127			}
128			i := 0
129			for i < len(key) {
130				c := key[i]
131				if c >= 'A' && c <= 'Z' {
132					c += 'a' - 'A'
133				}
134				if c != field[i] {
135					break
136				}
137				i++
138			}
139			if i == len(field) {
140				return field
141			}
142		}
143		return ""
144	}
