146	// envelopeFieldLookalike reports the standard lowercase name of one of the
147	// five envelope fields when key names it under a spelling encoding/json's
148	// struct-tag matching would fold onto the field but which is not an accepted
149	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
150	// matching folds with the Unicode simple case-folding rules
151	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
152	// the JSON escape u017f — keys arrive here already unescaped) names the
153	// circuits field exactly like "circuits", even standing alone. Such a
154	// lookalike is damage whatever its value: a later "circuitſ": [] would
155	// otherwise override a populated circuits array through last-value-wins and
156	// the records would vanish on the next commit. A key that does not fold onto
157	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
158	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
159	// the ordinary unknown-member handling.
160	func envelopeFieldLookalike(key string) string {
161		if canonicalEnvelopeField(key) != "" {
162			return "" // an accepted ASCII spelling, not a lookalike
163		}
164		for _, field := range envelopeTopFields {
165			if strings.EqualFold(key, field) {
166				return field
167			}
